     * cancelled, or the sheet's today changes. Refused (403) for a viewer, (409) for a claim that is
     * not DRAFT or is locked by another user, and (423) when dated inside a closed period; a refused
     * claim takes no lock. Any other claim of the same person the user had locked is released.
     */
    @Transactional
    public Claim lock(String sheetId, String user, long id) {
        roles.refuseViewer(sheetId, user);
        // hold the sheet so two users cannot both take the lock
        sheets.lock(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
        refuseIfNotEditable(sheetId, user, claim);
        periods.refuseIfClosed(sheetId, claim.getDueBy());
        for (Claim other : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId())) {
            if (other.getId() != id && user.equals(other.getLockedBy())) {
                other.setLockedBy(null);
                claims.save(other);
            }
        }
        claim.setLockedBy(user);
        return claims.saveAndFlush(claim);
    }

    /** Cancel a claim's editor: the user's lock on the claim is released; another user's lock stays. */
    @Transactional
    public Claim unlock(String sheetId, String user, long id) {
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
        if (user.equals(claim.getLockedBy())) {
            claim.setLockedBy(null);
            claim = claims.saveAndFlush(claim);
        }
        return claim;
    }

    /** Refuse (409) editing a claim that is not DRAFT, or that another user's open editor locks. */
    private static void refuseIfNotEditable(String sheetId, String user, Claim claim) {
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be edited.");
        }
        if (claim.isLockedAgainst(user)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "This claim is being edited by " + claim.getLockedBy() + ".");
        }
    }

    /**
     * Move a claim to a new status, refused (409) when its current status does not allow it,
     * refused (403) when the user who opened it tries to settle it, and refused (422) settling a
     * claim above the proof threshold with no proofs. A clerk settling one whose
     * figure is above the sheet's clerk limit makes it PENDING instead.
     */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
        return changeStatus(sheetId, user, id, next, null, false, null, false);
    }

    /**
     * Void a claim, as {@link #changeStatus(String, String, long, ClaimStatus)}, with a reason from
     * the sheet's void reasons: while the sheet has any, a void without one of them is refused (422).
     */
    @Transactional
    public Claim voidClaim(String sheetId, String user, long id, String voidReason) {
        return changeStatus(sheetId, user, id, ClaimStatus.VOID, null, false, voidReason, false);
    }

    /**
     * Approve a PENDING claim: it becomes SETTLED, its due fixed at its figure (the one a statement bound, else its live one) with its late
     * charge on the sheet's today. Refused (409) when not PENDING, and (403) for a clerk or the
     * user who opened it.
     */
    @Transactional
    public Claim approve(String sheetId, String user, long id) {
        return changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null, true, null, false);
    }

    /**
     * Reject a PENDING claim with a reason: it is OPEN again, still bound by the last statement if
     * that statement included it. Refused (409) when not PENDING, and (403) for a clerk.
     */
    @Transactional
    public Claim reject(String sheetId, String user, long id, String reason) {
        return changeStatus(sheetId, user, id, ClaimStatus.OPEN, reason, true, null, false);
    }

    /**
     * Settle a claim as of a date on or before the sheet's today, as
     * {@link #changeStatus(String, String, long, ClaimStatus)} does, its due fixed at {@code due}: the
     * claim's due as it stood at the end of that date (see {@link ClaimAsOf}). CLAIM_SETTLED gains the
     * date as {@code on=}.
     */
    @Transactional
    public Claim settleAsOf(String sheetId, String user, long id, LocalDate on, BigDecimal due) {
        return changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null, false, null, false, on, due);
    }

    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
            boolean review, String voidReason, boolean judged) {
        return changeStatus(sheetId, user, id, next, reason, review, voidReason, judged, null, null);
    }

    /**
     * Move a claim to a new status; {@code review} for a steward's approval or rejection of a PENDING
     * claim, {@code judged} when the four-eyes and proof rules were already judged on the claim it was
     * split off (see {@link #partSettle}); {@code on} when settling as of that date, at the due
     * {@code asOfDue} it had then.
     */
    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
            boolean review, String voidReason, boolean judged, LocalDate on, BigDecimal asOfDue) {
        roles.refuseViewer(sheetId, user);
        if (!review) {

content.content:
    if (!review) {
        roles.refuseUnlessPermitted(sheetId, user, switch (next) {
            case OPEN -> "open";
            case SETTLED -> "settle";
            case VOID -> "void";
            default -> throw new IllegalStateException();
        });
    }
    // lock the sheet's numbering before reading the claim, so a claim is settled (and numbered) once
    if (next == ClaimStatus.SETTLED) {
        sheets.lock(sheetId);
    }
    RollupService.Snapshot before = rollup.snapshot(sheetId);
    Claim claim = claims.findByIdAndSheetId(id, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
    ClaimStatus was = claim.getStatus();
    // only a steward's review moves a PENDING claim on, other than voiding it
    // only a steward's review (see #review) moves a REVIEW claim on, other than voiding it
    if (!was.canBecome(next) || (next != ClaimStatus.VOID && review != (was == ClaimStatus.PENDING))
            || (next != ClaimStatus.VOID && was == ClaimStatus.REVIEW)) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A " + claim.getStatus() + " claim cannot become " + next + ".");
    }
    periods.refuseIfClosed(sheetId, claim.getDueBy());
    boolean reversing = was == ClaimStatus.SETTLED;
    if (reversing) {
        refuseVoidSettled(sheetId, user, claim);
    }
    if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then.");
    }
    if (next == ClaimStatus.SETTLED && !judged && user.equals(claim.getOpenedBy())) {
        throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                "The user who opened a claim cannot " + (review ? "approve" : "settle") + " it.");
    }
    if (next == ClaimStatus.SETTLED && !judged && user.equals(claim.getEditedBy())) {
        throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                "The user who last edited a claim cannot " + (review ? "approve" : "settle") + " it.");
    }
    Person person = person(sheetId, claim.getPersonId());
    if (review && !isSteward(sheetId, user) && !user.equals(person.getApprover())) {
        throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                "Only a steward or the person's approver can approve or reject a PENDING claim.");
    }
    String voidedWith = next == ClaimStatus.VOID ? voidReasons.refuseUnlessListed(sheetId, voidReason) : null;
    if (next == ClaimStatus.OPEN && !review && flaggedAgainst(sheetId, user, person)) {
        throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                "This person is flagged: only a steward can open their claims.");
    }
    if (next == ClaimStatus.OPEN && !review && atPeriodCap(sheetId, claim)) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "This person already has as many open claims in that period as it allows.");
    }
    if (next == ClaimStatus.OPEN && !review && atMaxOpen(sheetId, claim)) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "This person already has as many open claims as the sheet allows.");
    }
    if (next == ClaimStatus.OPEN && !review && needsNote(sheetId, person, claim)) {
        throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
                "A claim due above the note threshold cannot be opened with an empty note.");
    }
    if (next == ClaimStatus.OPEN && !review && needsReview(sheetId, person, claim)) {
        next = ClaimStatus.REVIEW;
    }
    // settling fixes the figure with its late charge as it stands on the sheet's today (a
    // PENDING claim keeps any figure a statement bound)
    BigDecimal settling = next != ClaimStatus.SETTLED ? null
            : on != null ? asOfDue : charged(sheetId, person, claim);
    if (next == ClaimStatus.SETTLED && !judged && needsProof(sheetId, person, claim, settling)) {
        throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
                "A claim due above the proof threshold cannot be " + (review ? "approved" : "settled")
                        + " without a proof of each kind the sheet needs.");
    }
    if (next == ClaimStatus.SETTLED && !review && aboveClerkLimit(sheetId, user, person, claim, settling)) {
        next = ClaimStatus.PENDING;
        settling = null;
    }
    claim.setStatus(next);
    if (next == ClaimStatus.OPEN && !review) {
        claim.setOpenedBy(user);
    } else if (next == ClaimStatus.REVIEW) {
        claim.setOpenedBy(user);
        claim.setReviewOn(sheets.today(sheetId));
    } else if (next == ClaimStatus.PENDING) {
        claim.setPendingOn(sheets.today(sheetId));
    } else if (next == ClaimStatus.SETTLED) {
        claim.setSettledDue(settling);
        // a claim takes its number when settled; one numbered before keeps it
        if (claim.getNumber() == null) {
            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDueBy()));
        }
    } else if (next == ClaimStatus.VOID) {
        claim.setVoidReason(voidedWith);
    }
    logStatus(sheetId, user, person, claim);
    Claim saved = claims.saveAndFlush(claim);
    String event = switch (next) {
        case OPEN -> review ? "CLAIM_REJECTED" : "CLAIM_OPENED";
        case PENDING -> "CLAIM_PENDING";
        case SETTLED -> review ? "CLAIM_APPROVED" : "CLAIM_SETTLED";
        case VOID -> "CLAIM_VOIDED";
        case REVIEW -> "CLAIM_REVIEW";
        case DRAFT, DELETED -> throw new IllegalStateException();
    };
    audit.recordOnCommit(record(event, sheetId, user, person, saved)
            + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
            + (next == ClaimStatus.SETTLED ? " due=" + dueText(saved.getSettledDue()) : "")
            + (reason != null ? " reason=" + reason : "")
            + (reversing ? " reversed=" + dueText(saved.getSettledDue()) : "")
            + (voidedWith != null ? " reason=" + voidedWith : "")
            + (next == ClaimStatus.SETTLED && on != null ? " on=" + on : ""));
    if (next == ClaimStatus.SETTLED) {
        notifyWatchers(sheetId, user, person, saved);
    }
    rollup.recordChanges(sheetId, user, before);
    return saved;
}

/**
 * A steward's review of a REVIEW claim: it becomes OPEN, still unnumbered, keeping who
 * opened it; CLAIM_REVIEWED is written, then CLAIM_OPENED. Refused (403) for
 * anyone but a steward, (409) for a claim that is not REVIEW and (423) when due inside a closed
 * period.
 */
@Transactional
public Claim review(String sheetId, String user, long id) {
    roles.refuseViewer(sheetId, user);
    RollupService.Snapshot before = rollup.snapshot(sheetId);
    Claim claim = claims.findByIdAndSheetId(id, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
    if (claim.getStatus() != ClaimStatus.REVIEW) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A " + claim.getStatus() + " claim cannot be reviewed.");
    }
    if (!isSteward(sheetId, user)) {
        throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can review a claim.");
    }
    periods.refuseIfClosed(sheetId, claim.getDueBy());
    Person person = person(sheetId, claim.getPersonId());
    claim.setStatus(ClaimStatus.OPEN);
    logStatus(sheetId, user, person, claim);
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("CLAIM_REVIEWED", sheetId, user, person, saved));
    audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, saved)
            + (saved.getNumber() != null ? " number=" + saved.getNumber() : ""));
    rollup.recordChanges(sheetId, user, before);
    return saved;
}

/**
 * A steward's assignment of a REVIEW claim to a user: the claim shows them until assigned again;
 * REVIEW_ASSIGNED is written, naming the user. Refused (403) for anyone but a steward, (400) for a
 * blank user and (409) for a claim that is not REVIEW.
 */
@Transactional
public Claim assignReview(String sheetId, String user, long id, String assignee) {
    roles.refuseViewer(sheetId, user);
    if (!isSteward(sheetId, user)) {
        throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can assign a review.");
    }
    String name = assignee == null ? "" : assignee.trim();
    if (name.isEmpty()) {
        throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Name the user to assign the review to.");
    }
    Claim claim = claims.findByIdAndSheetId(id, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
    if (claim.getStatus() != ClaimStatus.REVIEW) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A " + claim.getStatus() + " claim cannot be assigned for review.");
    }
    Person person = person(sheetId, claim.getPersonId());
    claim.setReviewAssigned(name);
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("REVIEW_ASSIGNED", sheetId, user, person, saved) + " user=" + name);
    return saved;
}

/**
 * Delete a DRAFT claim: it becomes DELETED, counts nowhere and makes no other move but a restore;
 * its status log gains a DELETED line and CLAIM_DELETED is written. Any editor's lock on it is
 * released. Refused (403) for a viewer, (409) for a claim that is not DRAFT or that another
 * user's open editor locks, and (423) when due inside a closed period.
 */
@Transactional
public Claim delete(String sheetId, String user, long id) {
    roles.refuseViewer(sheetId, user);
    RollupService.Snapshot before = rollup.snapshot(sheetId);
    Claim claim = claims.findByIdAndSheetId(id, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
    if (!claim.getStatus().canBecome(ClaimStatus.DELETED)) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A " + claim.getStatus() + " claim cannot be deleted.");
    }
    if (claim.isLockedAgainst(user)) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "This claim is being edited by " + claim.getLockedBy() + ".");
    }
    periods.refuseIfClosed(sheetId, claim.getDueBy());
    Person person = person(sheetId, claim.getPersonId());
    claim.setStatus(ClaimStatus.DELETED);
    claim.setLockedBy(null);
    logStatus(sheetId, user, person, claim);
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("CLAIM_DELETED", sheetId, user, person, saved));
    rollup.recordChanges(sheetId, user, before);
    return saved;
}

/**
 * Restore a DELETED claim to DRAFT, on the sheet-today it was deleted (the date its status log
 * records it DELETED): its log gains a DRAFT line and CLAIM_RESTORED is written. Refused (403)
 * for a viewer, (409) for a claim that is not DELETED or on a later (or earlier) sheet-today, and
 * (423) when due inside a closed period.
 */
@Transactional
public Claim restore(String sheetId, String user, long id) {
    roles.refuseViewer(sheetId, user);
    RollupService.Snapshot before = rollup.snapshot(sheetId);
    Claim claim = claims.findByIdAndSheetId(id, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
    if (!claim.getStatus().canBecome(ClaimStatus.DRAFT)) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A " + claim.getStatus() + " claim cannot be restored.");
    }
    LocalDate deleted = claim.getLog().stream().filter(entry -> entry.getStatus() == ClaimStatus.DELETED)
            .map(ClaimLogEntry::getDate).reduce((first, last) -> last).orElse(null);
    if (deleted == null || !deleted.equals(sheets.today(sheetId))) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A DELETED claim can be restored only on the day it was deleted.");
    }
    periods.refuseIfClosed(sheetId, claim.getDueBy());
    Person person = person(sheetId, claim.getPersonId());
    claim.setStatus(ClaimStatus.DRAFT);
    logStatus(sheetId, user, person, claim);
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("CLAIM_RESTORED", sheetId, user, person, saved));
    rollup.recordChanges(sheetId, user, before);
    return saved;
}

/**
 * Refuse voiding a SETTLED claim: (403) for anyone but a steward, and (409) once the sheet's
 * today is more than {@value #VOID_SETTLED_DAYS} days after its settlement (or before it).
 */
private void refuseVoidSettled(String sheetId, String user, Claim claim) {
    if (!isSteward(sheetId, user)) {
        throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a SETTLED claim.");
    }
    LocalDate settled = claim.getLog().stream().filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
            .map(ClaimLogEntry::getDate).reduce((first, last) -> last).orElse(null);
    LocalDate today = sheets.today(sheetId);
    if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
        throw new ResponseStatusException(HttpStatus.CONFLICT, "A SETTLED claim can be voided only within "
                + VOID_SETTLED_DAYS + " days of its settlement.");
    }
}

/** Record a notice of the claim for each user watching its person, in the order they started watching. */
private void notifyWatchers(String sheetId, String user, Person person, Claim claim) {
    for (Watch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
        audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + user + " user=" + watch.getUserName()
                + " person=" + person.getName() + " number=" + claim.getNumber());
    }
}

/**
 * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it
 * the claim counts in no total, is not overdue and cannot be settled; a statement it is bound
 * by stays as it is. Deferred while a statement binds it, the claim stays in the totals, counts
 * and can be settled while bound: the deferral takes effect only once the binding ends. Refused (409) for a claim that is not OPEN, (400) for a date
 * not after the sheet's today and (423) when dated inside a closed period.
 */
@Transactional
public Claim defer(String sheetId, String user, long id, LocalDate until) {
    roles.refuseViewer(sheetId, user);
    RollupService.Snapshot before = rollup.snapshot(sheetId);
    Claim claim = claims.findByIdAndSheetId(id, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
    if (claim.getStatus() != ClaimStatus.OPEN) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A " + claim.getStatus() + " claim cannot be deferred.");
    }
    if (!until.isAfter(sheets.today(sheetId))) {
        throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                "A claim can only be deferred to a date after the sheet's today.");
    }
    periods.refuseIfClosed(sheetId, claim.getDueBy());
    Person person = person(sheetId, claim.getPersonId());
    claim.setDeferredUntil(until, sheets.today(sheetId));
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("CLAIM_DEFERRED", sheetId, user, person, saved)
            + (saved.getNumber() != null ? " number=" + saved.getNumber() : "") + " until=" + until);
    rollup.recordChanges(sheetId, user, before);
    return saved;
}

/**
 * Raise a claim's proofs count by one, with a proof of a kind (receipt or photo; null for none
 * chosen, a receipt). Refused (400) for any other kind, (409) for a SETTLED or VOID claim and (423) when
 * dated inside a closed period.
 */
@Transactional
public Claim addProof(String sheetId, String user, long id, String kind) {
    roles.refuseViewer(sheetId, user);
    if (kind != null && !Claim.PROOF_KINDS.contains(kind)) {
        throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A proof is a receipt or a photo.");
    }
    Claim claim = claims.findByIdAndSheetId(id, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
    if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
            || claim.getStatus() == ClaimStatus.DELETED) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A " + claim.getStatus() + " claim cannot have a proof added.");
    }
    periods.refuseIfClosed(sheetId, claim.getDueBy());
    Person person = person(sheetId, claim.getPersonId());
    claim.addProof(kind);
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("CLAIM_PROOF_ADDED", sheetId, user, person, saved)
            + (saved.getNumber() != null ? " number=" + saved.getNumber() : "") + " proofs=" + saved.getProofs()
            + (kind != null ? " kind=" + kind : ""));
    return saved;
}

/**
 * Add a line to a DRAFT claim: its amount becomes the total of its lines (quantity times unit
 * amount), written as CLAIM_LINE_ADDED with the new amount. It counts as editing the claim.
 * Refused as an edit is: (409) for a claim that is not DRAFT or that another user's editor locks,
 * and (423) when due inside a closed period. An editor the user has open on the claim stays open.
 */
@Transactional
public Claim addLine(String sheetId, String user, long id, String label, int qty, BigDecimal unit) {
    roles.refuseViewer(sheetId, user);
    Claim claim = claims.findByIdAndSheetId(id, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
    refuseIfNotEditable(sheetId, user, claim);
    periods.refuseIfClosed(sheetId, claim.getDueBy());
    Person person = person(sheetId, claim.getPersonId());
    RollupService.Snapshot before = rollup.snapshot(sheetId);
    claim.addLine(new ClaimLine(label, qty, unit));
    claim.setEditedBy(user);
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("CLAIM_LINE_ADDED", sheetId, user, person, saved) + " label=" + label + " qty="
            + qty + " unit=" + unit.toPlainString());
    rollup.recordChanges(sheetId, user, before);
    return saved;
}

/**
 * Share a claim with another person on the sheet at a share percent (more than 0.00), written as
 * CLAIM_SHARED with the holder and the share. Refused (409) for a SETTLED, VOID or DELETED claim,
 * for the claim's own person or a person already holding a share, and (422) for a share of 0.00
 * or one taking the claim's shares above 100.00.
 */
@Transactional
public Claim share(String sheetId, String user, long id, long holderId, BigDecimal share) {
    roles.refuseViewer(sheetId, user);
    Claim claim = claims.findByIdAndSheetId(id, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
    if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
            || claim.getStatus() == ClaimStatus.DELETED) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A " + claim.getStatus() + " claim cannot be shared.");
    }
    Person person = person(sheetId, claim.getPersonId());
    Person holder = person(sheetId, holderId);
    if (holder.getId().equals(person.getId())) {
        throw new ResponseStatusException(HttpStatus.CONFLICT, "A claim cannot be shared with its own person.");
    }
    if (claim.getShares().stream().anyMatch(s -> s.getHolderId().equals(holder.getId()))) {
        throw new ResponseStatusException(HttpStatus.CONFLICT, holder.getName() + " already holds a share.");
    }
    if (share.signum() <= 0) {
        throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "A share must be more than 0.00.");
    }
    if (claim.sharedTotal().add(share).compareTo(BigDecimal.valueOf(100)) > 0) {
        throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
                "The claim's shares cannot total more than 100.00.");
    }
    RollupService.Snapshot before = rollup.snapshot(sheetId);
    claim.addShare(new ClaimShare(holder.getId(), share));
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("CLAIM_SHARED", sheetId, user, person, saved) + " with=" + holder.getName()
            + " share=" + share.toPlainString());
    rollup.recordChanges(sheetId, user, before);
    return saved;
}

/**
 * Comment on a claim in any status: kept with the user and the sheet's today, and written as
 * COMMENT_ADDED. Refused (422) for an empty comment, and as any change for a viewer or an
 * archived sheet.
 */
@Transactional
public Claim comment(String sheetId, String user, long id, String text) {
    roles.refuseViewer(sheetId, user);
    Claim claim = claims.findByIdAndSheetId(id, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
    if (text.isEmpty()) {
        throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "A comment cannot be empty.");
    }
    Person person = person(sheetId, claim.getPersonId());
    claim.comment(new ClaimComment(user, sheets.today(sheetId), text));
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("COMMENT_ADDED", sheetId, user, person, saved)
            + (saved.getNumber() != null ? " number=" + saved.getNumber() : "") + " text=" + text);
    return saved;
}

/**
 * Remind an OPEN or PENDING claim: write REMIND and mark it reminded on the sheet's today. With an
 * escalation gap set, a claim never escalated whose previous reminder was at least that many days
 * before the sheet's today is escalated too: ESCALATE is written after REMIND.
 * Refused (409) for a claim in any other status or already reminded on the sheet's today.
 */
@Transactional
public Claim remind(String sheetId, String user, long id) {
    roles.refuseViewer(sheetId, user);
    Claim claim = claims.findByIdAndSheetId(id, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
    if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A " + claim.getStatus() + " claim cannot be reminded.");
    }
    LocalDate today = sheets.today(sheetId);
    if (today.equals(claim.getRemindedOn())) {
        throw new ResponseStatusException(HttpStatus.CONFLICT, "This claim was already reminded today.");
    }
    Person person = person(sheetId, claim.getPersonId());
    Integer gap = sheets.load(sheetId, user).getEscalateAfter();
    boolean escalate = gap != null && !claim.isEscalated() && claim.getRemindedOn() != null
            && !claim.getRemindedOn().plusDays(gap).isAfter(today);
    claim.setRemindedOn(today);
    if (escalate) {
        claim.setEscalated(true);
    }
    Claim saved = claims.saveAndFlush(claim);
    String number = saved.getNumber() != null ? " number=" + saved.getNumber() : "";
    audit.recordOnCommit(record("REMIND", sheetId, user, person, saved) + number);
    if (escalate) {
        audit.recordOnCommit(record("ESCALATE", sheetId, user, person, saved) + number);
    }
    return saved;
}

/**
 * A steward's waiver of an OPEN or PENDING claim's late charge: from then on it bears none,
 * whatever its overdue state; CLAIM_WAIVED is written. Refused (403) for anyone but a steward and
 * (409) for a claim in any other status or already waived.
 */
@Transactional
public Claim waive(String sheetId, String user, long id) {
    roles.refuseViewer(sheetId, user);
    if (!isSteward(sheetId, user)) {
        throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can waive a late charge.");
    }
    RollupService.Snapshot before = rollup.snapshot(sheetId);
    Claim claim = claims.findByIdAndSheetId(id, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
    if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A " + claim.getStatus() + " claim's late charge cannot be waived.");
    }
    if (claim.isWaived()) {
        throw new ResponseStatusException(HttpStatus.CONFLICT, "This claim's late charge is already waived.");
    }
    Person person = person(sheetId, claim.getPersonId());
    claim.waive();
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("CLAIM_WAIVED", sheetId, user, person, saved)
            + (saved.getNumber() != null ? " number=" + saved.getNumber() : ""));
    rollup.recordChanges(sheetId, user, before);
    return saved;
}

/**
 * Hold an OPEN or PENDING claim, or release it when held: a held claim still counts in every total.
 * CLAIM_HELD or CLAIM_RELEASED is
 * written. Refused (409) for a claim in any other status.
 */
@Transactional
public Claim toggleHold(String sheetId, String user, long id) {
    roles.refuseViewer(sheetId, user);
    RollupService.Snapshot before = rollup.snapshot(sheetId);
    Claim claim = claims.findByIdAndSheetId(id, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
    if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A " + claim.getStatus() + " claim cannot be held or released.");
    }
    Person person = person(sheetId, claim.getPersonId());
    boolean hold = !claim.isHeld();
    claim.setHeld(hold, sheets.today(sheetId));
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record(hold ? "CLAIM_HELD" : "CLAIM_RELEASED", sheetId, user, person, saved)
            + (saved.getNumber() != null ? " number=" + saved.getNumber() : ""));
    rollup.recordChanges(sheetId, user, before);
    return saved;
}

