307	    /**
308	     * Settle the given claims together, all or nothing: in list order (the order people were added,
309	     * newest claim first within a person), each by exactly the rules of settling one claim. A claim
310	     * a clerk's settle makes PENDING counts as settled. When any selected claim cannot be settled
311	     * (or is not on the sheet), none is: every one counts as refused and nothing is written. Else the
312	     * settle is a batch: it takes the sheet's next batch number, each claim is marked with it, and
313	     * after the claims' own records one BATCH_SETTLED record gives the batch, its count and the
314	     * frozen dues of those SETTLED added up, n/a skipped.
315	     */
316	    @Transactional
317	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> ids) {
318	        List<Claim> selected = inListOrder(sheetId, ids);
319	        int requested = (int) ids.stream().distinct().count();
320	        List<Claim> settled = new ArrayList<>();
321	        boolean refusedAny = selected.size() < requested;
322	        for (Claim claim : selected) {
323	            if (refusedAny) {
324	                break;
325	            }
326	            try {
327	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
328	            } catch (ResponseStatusException refusedOne) {
329	                refusedAny = true;
330	            }
331	        }
332	        if (refusedAny || settled.isEmpty()) {
333	            // undo the claims already settled, and the records waiting for the commit with them
334	            TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
335	            return new BulkSettled(0, requested, List.of(), sheets.sheet(sheetId).getLastBatch());
336	        }
337	        int batch = sheets.nextBatch(sheetId);
338	        List<Claim> batched = new ArrayList<>();
339	        BigDecimal total = BigDecimal.ZERO;
340	        for (Claim claim : settled) {
341	            claim.setBatch(batch);
342	            batched.add(claims.saveAndFlush(claim));
343	            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) { // n/a skipped
344	                total = total.add(claim.getSettledDue());
345	            }
346	        }
347	        audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + batch
348	                + " count=" + batched.size() + " total=" + dueText(total));
349	        return new BulkSettled(batched.size(), 0, batched, batch);
