382	    /**
383	     * Re-date the given claims to one date together, in list order (the order people were added,
384	     * newest claim first within a person), each by exactly the rules of re-dating one claim. A claim
385	     * that cannot be re-dated is refused and left as it is.
386	     */
387	    @Transactional
388	    public BulkRedated bulkRedate(String sheetId, String user, Collection<Long> ids, LocalDate date) {
389	        List<Claim> selected = inListOrder(sheetId, ids);
390	        int refused = (int) ids.stream().distinct().count() - selected.size();
391	        List<Claim> redated = new ArrayList<>();
392	        for (Claim claim : selected) {
393	            try {
394	                redated.add(redate(sheetId, user, claim.getId(), date));
395	            } catch (ResponseStatusException refusedOne) {
396	                // every refusal is checked before the claim is changed, so it is left as it is
397	                refused++;
398	            }
399	        }
400	        return new BulkRedated(redated.size(), refused, redated);
401	    }
