407	    /**
408	     * Void the given claims together with one reason, in list order (the order people were added,
409	     * newest claim first within a person), each by exactly the rules of voiding one claim (see
410	     * {@link #voidClaim}). A claim that cannot be voided is refused and left as it is.
411	     */
412	    @Transactional
413	    public BulkVoided bulkVoid(String sheetId, String user, Collection<Long> ids, String voidReason) {
414	        List<Claim> selected = inListOrder(sheetId, ids);
415	        int refused = (int) ids.stream().distinct().count() - selected.size();
416	        List<Claim> voided = new ArrayList<>();
417	        for (Claim claim : selected) {
418	            try {
419	                voided.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.VOID, null, false, voidReason,
420	                        false));
421	            } catch (ResponseStatusException refusedOne) {
422	                // every refusal is checked before the claim is changed, so it is left as it is
