429	    /** The given claims on the sheet in list order: people by position, newest claim first within a person. */
430	    private List<Claim> inListOrder(String sheetId, Collection<Long> ids) {
431	        Map<Long, Integer> personOrder = new HashMap<>();
432	        List<Person> listed = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
433	        for (int i = 0; i < listed.size(); i++) {
434	            personOrder.put(listed.get(i).getId(), i);
435	        }
436	        return ids.stream().distinct()
437	                .flatMap(id -> claims.findByIdAndSheetId(id, sheetId).stream())
438	                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
439	                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
440	                .toList();
441	    }
442	
443	    /**
444	     * The due on a claim's amount at the rate for the person's grade in force on the claim's date
445	     * (the sheet's own, else its nearest ancestor's: see {@link RateChain}),
446	     * rounded to the cent as the claim rounds (see {@link Rounding}), not raised to the floor (see {@link LateCharge});
447	     * null with no rate in force then.
448	     */
449	    public BigDecimal due(String sheetId, Person person, Claim claim) {
450	        Sheet sheet = sheets.sheet(sheetId);
451	        RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
452	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim).map(Rate::getPct)
453	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding))
454	                .orElse(null);
455	    }
456	
457	    /** What a candidate rate would change: how many claims would show a different due, and the sum of new minus current. */
458	    public record RatePreview(int count, BigDecimal diff) {
459	    }
460	
461	    /**
462	     * Preview a candidate rate for a grade, as if it applied to that grade on every date: of the
463	     * OPEN and PENDING claims whose person has the grade on the claim's date, how many would show a
464	     * different due and the sum of the differences (new due minus current due). A claim bound by a
465	     * statement keeps its figure; a claim with no due counts as 0.00. Nothing is saved.
466	     */
467	    @Transactional(readOnly = true)
468	    public RatePreview previewRate(String sheetId, String grade, BigDecimal pct) {
469	        Sheet sheet = sheets.sheet(sheetId);
470	        Map<Long, Person> byId = new HashMap<>();
471	        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
472	            byId.put(p.getId(), p);
473	        }
474	        int count = 0;
475	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
476	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
477	            Person person = byId.get(claim.getPersonId());
478	            if (person == null || !claim.getStatus().isOpen() || !grade.equals(person.gradeOn(claim.getDate()))) {
479	                continue;
480	            }
481	            if (claim.isStated()) {
482	                continue;
483	            }
484	            BigDecimal current = charged(sheetId, person, claim);
485	            RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
486	            BigDecimal figure = claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding);
487	            BigDecimal next = LateCharge.withCharge(sheet, claim, grade, figure);
488	            BigDecimal was = current == null ? BigDecimal.ZERO : current;
489	            if (current == null || was.compareTo(next) != 0) {
490	                count++;
491	                diff = diff.add(next.subtract(was));
492	            }
493	        }
494	        return new RatePreview(count, diff.setScale(2, RoundingMode.UNNECESSARY));
495	    }
