497	    /** The date a claim rounds by: its own, or for a correction that of the claim it corrects. */
498	    private LocalDate roundingDate(String sheetId, Claim claim) {
499	        if (!claim.isCorrection() || claim.getCorrects() == null) {
500	            return claim.getDate();
501	        }
502	        return Rounding.dateOf(claim, claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()));
503	    }
504	
505	    /** Log the claim's status as it is now: by the user, on the sheet's today, with its due as computed now. */
506	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
507	        claim.log(new ClaimLogEntry(claim.getStatus(), user, sheets.today(sheetId),
508	                dueText(charged(sheetId, person, claim))));
509	    }
510	
511	    private static String dueText(BigDecimal due) {
512	        return due == null ? "n/a" : due.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
513	    }
514	
515	    /**
516	     * Whether a claim settling at the figure is above the proof threshold in force on its date (its
517	     * person's grade's then when it has one, else the sheet's) and has no proofs, or, while the sheet has
518	     * proof kinds, no proof of one of them.
519	     */
520	    private boolean needsProof(String sheetId, Person person, Claim claim, BigDecimal figure) {
521	        Sheet sheet = sheets.sheet(sheetId);
522	        BigDecimal threshold = sheet.proofThresholdFor(person.gradeOn(claim.getDate()), claim.getDate());
523	        boolean lacking = claim.getProofs() == 0
524	                || sheet.proofKindList().stream().anyMatch(k -> claim.proofsOf(k) == 0);
525	        return lacking && figure != null && threshold != null && figure.compareTo(threshold) > 0;
526	    }
527	
528	    /** Whether a claim's due is above the note threshold in force on its date and its note is empty. */
529	    private boolean needsNote(String sheetId, Person person, Claim claim) {
530	        if (claim.getNote() != null && !claim.getNote().isBlank()) {
531	            return false;
532	        }
533	        BigDecimal threshold = sheets.sheet(sheetId).noteThresholdOn(claim.getDate());
534	        BigDecimal due = threshold == null ? null : charged(sheetId, person, claim);
535	        return due != null && due.compareTo(threshold) > 0;
536	    }
537	
538	    /** Whether a claim's due is above the review threshold in force on its date. */
539	    private boolean needsReview(String sheetId, Person person, Claim claim) {
540	        BigDecimal threshold = sheets.sheet(sheetId).reviewThresholdOn(claim.getDate());
541	        BigDecimal due = threshold == null ? null : charged(sheetId, person, claim);
542	        return due != null && due.compareTo(threshold) > 0;
543	    }
544	
545	    /**
546	     * Whether the user is a clerk settling a claim whose figure is above the clerk limit in force on the
547	     * claim's date: its person's grade's (on the sheet's today) when one is set, else the sheet's.
548	     */
549	    private boolean aboveClerkLimit(String sheetId, String user, Person person, Claim claim, BigDecimal figure) {
550	        BigDecimal limit = figure == null ? null
551	                : sheets.clerkLimit(sheetId, person.gradeOn(sheets.today(sheetId)), claim.getDate());
552	        return figure != null && limit != null && figure.compareTo(limit) > 0 && !isSteward(sheetId, user);
553	    }
554	
555	    private boolean isSteward(String sheetId, String user) {
556	        return Role.STEWARD.equals(roles.roleOf(sheetId, user));
557	    }
558	
559	    /**
560	     * The number a claim corrects: none unless its amount is negative, when it must name the number
561	     * of a SETTLED claim of the same person, else it is refused (400). It may not exceed what remains
562	     * of that claim: its amount less the corrections already made against it (VOID and DELETED ones,
563	     * and the claim being edited, left out), else it is refused (422).
564	     */
565	    private String corrected(String sheetId, long personId, Long editedId, BigDecimal amount, String corrects) {
566	        if (amount.signum() >= 0) {
567	            return null;
568	        }
569	        List<Claim> personClaims = corrects == null ? List.of()
570	                : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
571	        Claim target = personClaims.stream()
572	                .filter(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED)
573	                .findFirst().orElse(null);
574	        if (target == null) {
575	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
576	                    "A negative amount must correct a SETTLED claim of the same person, by its number.");
577	        }
578	        BigDecimal remaining = personClaims.stream()
579	                .filter(c -> corrects.equals(c.getCorrects()) && c.isCorrection()
580	                        && c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED
581	                        && !c.getId().equals(editedId))
582	                .map(Claim::getAmount).reduce(target.getAmount(), BigDecimal::add);
583	        if (amount.negate().compareTo(remaining) > 0) {
584	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
585	                    "A correction may not exceed what remains of the claim it corrects (" + remaining + ").");
586	        }
587	        return corrects;
588	    }
