      settled: trimmedSum(each.map((t) => t.settled)),
      open: trimmedSum(each.map((t) => t.open)),
    };
  });
  protected readonly dueText = dueText;
  protected readonly money = money;
  protected readonly cents = cents;
  /** The figures of the sheet's descendants as the store holds them, added to its own for the consolidated figures. */
  protected readonly descendants = signal<Descendants>(NO_DESCENDANTS);
  /**
   * The figures over the sheet and its descendants. An as-of view shows every sheet of the tree as it
   * stood at the end of that day, adding the sheet's own figures as the store held them then; else the screen's own.
   */
  protected readonly consolidated = computed(() => {
    const d = this.descendants();
    const asOfOwn = this.session.asOf() ? d.own : null;
    const own = asOfOwn
      ? {
          people: asOfOwn.people.map((p) => ({
            names: p.names,
            due: p.dueTotal === null ? null : cents(p.dueTotal),
            overdue: cents(p.overdueTotal),
            settled: cents(p.settledTotal),
            open: cents(p.openTotal),
            cut: cents(p.cutTotal),
          })),
          grade: (g: string) => cents(asOfOwn.gradeDueTotals[g] ?? '0.00'),
          status: (s: string) => asOfOwn.statusCounts[s] ?? 0,
        }
      : {
          people: this.people().map((p) => ({
            names: [p.name, ...p.aliases],
            due: this.dueOf(p),
            overdue: this.overdueOf(p).cents,
            settled: this.settledOpenOf(p).settled,
            open: this.settledOpenOf(p).open,
            cut: this.cutTotalOf(p.id),
          })),
          grade: (g: string) => cents(this.gradeSummary().find((x) => x.grade === g)?.dueTotal ?? '0.00'),
          status: (s: string) => this.statusCount(s),
        };
    // the trim and the people count run once over every person of the tree
    const tree = [
      ...own.people,
      ...d.people.map((p) => ({
        names: p.names,
        due: p.dueTotal === null ? null : cents(p.dueTotal),
        overdue: cents(p.overdueTotal),
        settled: cents(p.settledTotal),
        open: cents(p.openTotal),
        cut: cents(p.cutTotal),
      })),
    ];
    return {
      peopleCount: distinctPeople(tree.map((p) => p.names)),
      dueTotal: money(trimmedSum(tree.map((p) => p.due).filter((d): d is number => d !== null))),
      overdueTotal: money(trimmedSum(tree.map((p) => p.overdue))),
      settledTotal: money(trimmedSum(tree.map((p) => p.settled))),
      openTotal: money(trimmedSum(tree.map((p) => p.open))),
      cutTotal: money(trimmedSum(tree.map((p) => p.cut))),
      grades: [...new Set([...this.session.grades(), ...Object.keys(d.gradeDueTotals)])].sort().map((grade) => ({
        grade,
        dueTotal: money(own.grade(grade) + cents(d.gradeDueTotals[grade] ?? '0.00')),
      })),
      statuses: SUMMARY_STATUSES.map((status) => ({
        status,
        count: own.status(status) + (d.statusCounts[status] ?? 0),
      })),
    };
  });
  /** How many claims of the sheet and its descendants are in a status, as the consolidated figures count them. */
  protected treeStatusCount(status: string): number {
    return this.consolidated().statuses.find((s) => s.status === status)?.count ?? 0;
  }
  /** How many overdue claims that count the sheet and its descendants have (the sheet's own as of the date, in an as-of view). */
  protected readonly treeOverdueCount = computed(() => {
    const d = this.descendants();
    const own = this.session.asOf() && d.own ? d.own.overdueCount : this.overdueTotals().count;
    return own + d.overdueCount;
  });
  /** The person on the sheet with the user's name, by name or alias (compared without regard to case). */
  private readonly me = computed(() => {
    const user = this.session.user()?.toLowerCase();
    if (!user) return undefined;
    return this.people().find(
      (p) => p.name.toLowerCase() === user || p.aliases.some((a) => a.toLowerCase() === user),
    );
