content.content:
  protected shownName(p: Person): string {
    return `${p.name} (${this.gradeToday(p)})`;
  }

  /** The date a claim's live figures round by (see {@link roundingDate}). */
  private roundOn(c: Claim): string {
    return roundingDate(c, this.claimsOf(c.personId));
  }

  protected claimsOf(personId: number): Claim[] {
    return this.claimsByPerson().get(personId) ?? [];
  }

  /**
   * The person's timeline: one line per dated thing about them, by date, and on a date their grade
   * changes, then claims (by their line's text), then holds, then retirements, then unretirements.
   */
  protected timelineOf(p: Person): string[] {
    const lines: { date: string; rank: number; text: string }[] = [];
    for (const g of p.grades) {
      if (g.from !== null) lines.push({ date: g.from, rank: 0, text: `grade ${g.grade}` });
    }
    for (const c of this.claimsOf(p.id)) {
      lines.push({ date: c.date, rank: 1, text: `claim ${c.amount} ${c.status}` });
    }
    for (const h of p.holds) {
      lines.push({ date: h.from, rank: 2, text: h.to !== null ? `hold to ${h.to}` : 'hold' });
    }
    for (const r of p.retirements) {
      lines.push({ date: r.from, rank: 3, text: 'retired' });
      lines.push({ date: r.to, rank: 4, text: 'unretired' });
    }
    if (p.retiredFrom !== null) lines.push({ date: p.retiredFrom, rank: 3, text: 'retired' });
    return lines
      .sort((a, b) => a.date.localeCompare(b.date) || a.rank - b.rank || (a.rank === 1 ? a.text.localeCompare(b.text) : 0))
      .map((l) => `${l.date} ${l.text}`);
  }

  protected claimedOf(personId: number): string {
    const p = this.peopleById().get(personId);
    return money(this.claimsOf(personId).reduce((sum, c) => sum + this.countedCents(p, c), 0));
  }

  /** A claim's amount in whole cents when it counts toward claimed, else nothing: a correction never does. */
  private countedCents(p: Person | undefined, c: Claim): number {
    return countsFor(p, c, this.session.figureDay()) && !isCorrection(c) ? cents(c.amount) : 0;
  }

  /**
   * Compare two snapshot dates: per person in list order, retired people included, their name, the due-total of the last
   * snapshot written when today moved away from the from-date (empty when none), and likewise for
   * the to-date or their due-total now when it is blank; each line trimmed.
   */
  protected async compareSnapshots(event: Event): Promise<void> {
    event.preventDefault();
    const sheet = this.session.sheet();
    const from = this.snapshotFrom();
    const to = this.snapshotTo();
    this.snapshotLines.set([]);
    // the snapshots are written when today moves, so read them afresh from the store
    let snapshots: Map<number, SnapshotLine[]>;
    try {
      const list = await firstValueFrom(this.http.post<Person[]>('/api/people/list', { sheet }));
      snapshots = new Map(list.map((p) => [p.id, p.snapshots]));
    } catch {
      snapshots = new Map(this.people().map((p) => [p.id, p.snapshots]));
    }
    if (this.session.sheet() !== sheet) return;
    const on = (p: Person, day: string) =>
      (snapshots.get(p.id) ?? p.snapshots).filter((n) => n.day === day).at(-1)?.dueTotal ?? '';
    this.snapshotLines.set(
      this.people().map((p) =>
        [p.name, on(p, from), to ? on(p, to) : dueText(this.dueOf(p))].join(' ').trim(),
      ),
    );
  }

  /**
   * Compare this sheet with another: per grade of this sheet's summary, the grade, this sheet's
   * due-total for it and the other sheet's (0.00 when no one is on it there); no lines when the
   * other sheet does not exist.
   */
  protected async compareWithSheet(event: Event): Promise<void> {
    event.preventDefault();
    const sheet = this.session.sheet();
    const other = this.compareSheet().trim();
    this.compareLines.set([]);
    if (!other) return;
    let theirs: { exists: boolean; gradeDueTotals: Record<string, string> };
    try {
      theirs = await firstValueFrom(
        this.http.post<{ exists: boolean; gradeDueTotals: Record<string, string> }>('/api/rollup/compare/list', {
          sheet: other,
        }),
      );
    } catch {
      return;
    }
    if (this.session.sheet() !== sheet || !theirs.exists) return;
    this.compareLines.set(
      this.gradeSummary().map((g) => `${g.grade} ${g.dueTotal} ${theirs.gradeDueTotals[g.grade] ?? '0.00'}`),
    );
  }

  /** What the person owes, in whole cents: the sum of their figures held to the sheet's cap less their cut total. */
  protected dueOf(p: Person): number | null {
    const sum = this.figuresOf(p);
    const room = this.roomOf(p);
    return sum === null || room === null ? sum : Math.min(sum, room);
  }

  /** The person's cut total, in whole cents: 0 when no pool shows them a cut. */
  protected cutTotalOf(id: number): number {
    return this.cutTotals().get(id) ?? 0;
  }

  /** How far the sum of the person's figures is above the cap less their cut total, in whole cents; 0 otherwise. */
  protected excessOf(p: Person): number {
    const sum = this.figuresOf(p);
    const room = this.roomOf(p);
    return sum === null || room === null ? 0 : Math.max(sum - room, 0);
  }

  /** The cap in force on the date of the person's latest claim that counts less their cut total (not below 0), in whole cents; null for no cap. */
  private roomOf(p: Person): number | null {
    const today = this.session.figureDay();
    const latest = this.claimsOf(p.id)
      .filter((c) => countsFor(p, c, today))
      .reduce<string | null>((max, c) => (max === null || c.date > max ? c.date : max), null);
    const cap = valueOn(this.caps(), latest ?? today, '');
    return cap === '' ? null : Math.max(cents(cap) - this.cutTotalOf(p.id), 0);
  }

  /**
   * The sum of the figures of the person's claims that count, in whole cents. Null when their
   * grade in force on the sheet's today has no rate in force then, unless a claim that counts has
   * a figure.
   */
  private figuresOf(p: Person): number | null {
    const figures = this.claimsOf(p.id)
      .filter((c) => countsFor(p, c, this.session.figureDay()))
      .map((c) => {
        const f = chargedDueCents(c, this.rates(), gradeOn(p.grades, c.date), this.floors(), this.lateness(), this.roundOn(c));
        return f === null ? null : ownPart(c, f, (s) => this.partOf(c, f, s));
      });
    const held = this.heldParts().get(p.id);
    if (this.pctOf().get(this.gradeToday(p)) === undefined && figures.every((f) => f === null) && held === undefined) {
      return null;
    }
    return figures.reduce<number>((sum, f) => sum + (f ?? 0), 0) + (held ? held.settled + held.open : 0);
  }

  /**
   * A holder's part of a claim, in whole cents (see {@link holderPart}): by the rate of the holder's
   * own grade on the claim's date, rounded as the claim rounds.
   */
  private partOf(c: Claim, figure: number, s: ClaimShareItem): number | null {
    const holder = this.peopleById().get(s.holder);
    const pct = holder === undefined ? undefined : pctOn(this.rates(), gradeOn(holder.grades, c.date), c.date, c);
    const late = this.lateness();
    return holderPart(c, figure, s.share, pct, roundsHalfUp(this.roundOn(c), late.policyDate, late.today, late.roundings));
  }

  /**
   * Per holder (by person id), the parts they hold of the claims that count for their own person and
   * have a figure, in whole cents, split into those of SETTLED claims and those of OPEN and PENDING
   * ones; a person holding none is absent.
   */
  private readonly heldParts = computed(() => {
    const today = this.session.figureDay();
    const parts = new Map<number, { settled: number; open: number }>();
    for (const c of this.claims()) {
      if ((c.shares ?? []).length === 0) continue;
      const owner = this.peopleById().get(c.personId);
      if (owner === undefined || !countsFor(owner, c, today)) continue;
      const figure = chargedDueCents(c, this.rates(), gradeOn(owner.grades, c.date), this.floors(), this.lateness(), this.roundOn(c));
      if (figure === null) continue;
      for (const s of c.shares) {
        const held = parts.get(s.holder) ?? { settled: 0, open: 0 };
        const part = this.partOf(c, figure, s);
        if (part === null) continue;
        parts.set(s.holder, isOpen(c) ? { ...held, open: held.open + part } : { ...held, settled: held.settled + part });
      }
    }
    return parts;
  });

  /**
   * The figures of the person's claims that count, in whole cents, split into those of their
   * SETTLED claims and those of their OPEN and PENDING claims; together the sum before the cap.
   */
  protected settledOpenOf(p: Person): { settled: number; open: number } {
    const out = { settled: 0, open: 0 };
    for (const c of this.claimsOf(p.id)) {
      if (!countsFor(p, c, this.session.figureDay())) continue;
      const figure = chargedDueCents(c, this.rates(), gradeOn(p.grades, c.date), this.floors(), this.lateness(), this.roundOn(c));
      const own = figure === null ? 0 : ownPart(c, figure, (s) => this.partOf(c, figure, s));
      if (isOpen(c)) out.open += own;
      else out.settled += own;
    }
    const held = this.heldParts().get(p.id);
    if (held) {
      out.settled += held.settled;
      out.open += held.open;
    }
    return out;
  }

  /**
